/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_products_after_insert` AFTER INSERT ON `tb_products` FOR EACH ROW BEGIN
    DECLARE rol_usuario VARCHAR(50);
    DECLARE usuario_real VARCHAR(255);

    SET usuario_real = USER();

    SELECT FROM_USER
    INTO rol_usuario
    FROM mysql.role_edges
    WHERE TO_USER = SUBSTRING_INDEX(usuario_real, '@', 1)
      AND TO_HOST = '%'
    LIMIT 1;

    IF rol_usuario IS NULL THEN
        SET rol_usuario = 'Sin rol';
    END IF;

    INSERT INTO tb_logs (
        table_name,
        table_operation,
        db_user,
        operation_description,
        operation_status
    )
    VALUES (
        'tb_products',
        'Create',
        usuario_real,
        CONCAT(
            'El usuario: ', SUBSTRING_INDEX(usuario_real, '@', 1),
            ' (', rol_usuario, ')',
            ' ha creado el producto. ID=', NEW.ID,
            ', SKU=', NEW.SKU,
            ', nombre=', NEW.name,
            ', precio=', NEW.current_price,
            ', stock=', NEW.current_stock
        ),
        b'1'
    );
END */;;
DELIMITER ;
